ETIQUETAS_GRUPO = {"Departamento": "Departamento", "Tiempo": "Tiempo · año y mes", "Educación": "Nivel educativo", "Demografía": "Demografía · sexo, etnia",
                   "Contrato": "Contrato y lugar de trabajo", "Sector": "Sector económico", "Oficio": "Oficio"}


def selector_grupo(pagina):
    """Pregunta + lista desplegable: el usuario elige la categoría y debajo se muestran sus gráficos. Devuelve el grupo elegido."""
    nombres = [g[0] for g in GRUPOS]
    k = f"grupo_{pagina}"
    if st.session_state.get(k) not in nombres:
        st.session_state[k] = nombres[0]
    with st.container(key=f"pill_{pagina}"):
        html('<div class="gq">¿Por cuál categoría te gustaría ver el análisis?</div>')
        v = st.selectbox("Categoría del análisis", nombres, key=k, format_func=lambda n: ETIQUETAS_GRUPO.get(n, n), label_visibility="collapsed")
    return v or nombres[0]


def bloque_graficos(df, tipo, pagina, ref, ref2, nac, grupo=None):
    elegido = grupo or GRUPOS[0][0]
    st.session_state[f"_grupo_{pagina}_ult"] = elegido
    for gi, (nombre_g, filas) in enumerate(GRUPOS):
        if nombre_g != elegido:
            continue
        if True:
            for fila in filas:
                ancho = len(fila) == 1 and fila[0][2].get("ancho")      # una sola tarjeta a todo el ancho, sin panel de detalle
                solo = len(fila) == 1 and not ancho
                cols = st.columns([2.4, 1], gap="large") if solo else st.columns(len(fila), gap="large")
                for i, (dim, tit, opts) in enumerate(fila):
                    base = f"{pagina}_{dim}"
                    d = datos_ranking(df, dim, tipo)
                    if f"{base}_sel" in st.session_state and st.session_state[f"{base}_sel"] not in d[dim].tolist():
                        st.session_state[f"{base}_sel"] = None
                    with cols[i]:
                        if opts.get("tendencia"):
                            tendencia_card(d.sort_values(dim, key=lambda s: s.map(lambda x: MESES_ORDEN.index(x) if x in MESES_ORDEN else x)),
                                           dim, tit, tipo, base)
                        elif dim == "sexo" and set(d["sexo"]) <= {"Femenino", "Masculino"} and len(d):
                            sexo_card(d, tipo, ref, base, nac)
                        elif dim == "departamento":
                            with st.container(key="sort_dep_" + pagina):
                                vista = st.segmented_control("Vista", ["Mapa", "Ranking"], default="Mapa", key=f"vista_{base}",
                                                             label_visibility="collapsed") or "Mapa"
                            if vista == "Mapa":
                                mapa_card(d, tipo, ref, base, nac)
                            else:
                                ranking_card(d, dim, tit, tipo, ref, base, nac, solo or bool(ancho), estrecho=len(fila) >= 3)
                        else:
                            ranking_card(d, dim, tit, tipo, ref, base, nac, solo or bool(ancho), estrecho=len(fila) >= 3)
                if solo and not fila[0][2].get("tendencia"):
                    with cols[1]:
                        base = f"{pagina}_{fila[0][0]}"
                        detalle_card(datos_ranking(df, fila[0][0], tipo), fila[0][0], tipo, ref, ref2, base, nac)
                        if gi == 0:  # la guía solo aparece en la primera pestaña
                            ayuda_card(pagina)


